param(
  [string]$ApiBaseUrl,
  [string]$SupabaseUrl='https://taosgvfdnblnopaywimf.supabase.co',
  [string]$SupabaseAnonKey='sb_publishable_cZtYQI3ApFTw8kU2a2AoBQ_nGdlSw1W',
  [string]$AuthCallbackUrl='https://getcompr.nl/auth-callback.html',
  [switch]$ValidationOnly,[switch]$StageConverterInput,[string]$OutputPath,
  [switch]$UseTestFixture,[switch]$ShowInventory
)
$ErrorActionPreference='Stop'
if(@($ValidationOnly,$StageConverterInput|Where-Object{$_}).Count-ne 1){throw 'Choose exactly one mode: -ValidationOnly or -StageConverterInput.'}
if($OutputPath-and-not $StageConverterInput){throw '-OutputPath requires -StageConverterInput.'}
if($UseTestFixture-and $ApiBaseUrl){throw 'Do not combine -UseTestFixture with -ApiBaseUrl.'}
$api=if($UseTestFixture){'https://api.compr.test'}elseif($ApiBaseUrl){$ApiBaseUrl.TrimEnd('/')}else{''}
function SafeUrl($value,$label,$fixture=$false){$u=$null;if(-not[uri]::TryCreate($value,[UriKind]::Absolute,[ref]$u)-or $u.Scheme-ne'https'){throw "$label must be HTTPS."};if(-not $fixture-and($u.UserInfo-or $u.Host-match'(?i)localhost|^127\.|^::1$|^\[::1\]$|\.invalid$|example\.(com|org|net)$')){throw "$label is unsafe."};$u}
if(-not $api){throw 'SAFARI_PRODUCTION_API_URL_REQUIRED'}
$apiUri=SafeUrl $api 'API URL' $UseTestFixture;$supabaseUri=SafeUrl $SupabaseUrl 'Supabase URL';$callbackUri=SafeUrl $AuthCallbackUrl 'Callback URL'
if($callbackUri.Host-ne'getcompr.nl'-or$callbackUri.AbsolutePath-ne'/auth-callback.html'-or$callbackUri.Query-or$callbackUri.Fragment){throw 'Auth callback must be exactly https://getcompr.nl/auth-callback.html.'}
if($SupabaseAnonKey-notmatch'^[A-Za-z0-9._-]{20,}$'-or$SupabaseAnonKey-match'(?i)service.role|secret|sk_live|sk_test'){throw 'Only a public Supabase key is allowed.'}
$root=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$source=Join-Path $root 'V.0.3-prototype';$platform=Join-Path $root 'platforms\safari';$build=[IO.Path]::GetFullPath((Join-Path $root 'build'));$tmp=[IO.Path]::GetFullPath((Join-Path $root 'tmp'))
Import-Module (Join-Path $PSScriptRoot 'extension-production-staging.psm1') -Force
$files=@(
'popup.html','popup.js','safari-popup.js','compare.html','compare.js','account.html','account.js','background.js','content.js','auth-receiver.html','auth-receiver.js','privacy.md',
'icons\icon16.png','icons\icon32.png','icons\icon48.png','icons\icon128.png','styles\popup.css','styles\compare.css','styles\account.css',
'shared\browserAdapter.js','shared\accountRoute.js','shared\productEligibility.js','shared\popupState.js','shared\safariExperience.js','shared\product.js','shared\currency.js','shared\similarity.js','shared\storage.js','shared\i18n.js','shared\auth.js','shared\apiClient.js','shared\reliability.js',
'detectors\price.js','detectors\brand.js','detectors\color.js','detectors\material.js','detectors\sizes.js','detectors\availability.js','detectors\policies.js','detectors\discountCodes.js','detectors\category.js','detectors\productId.js','detectors\productName.js',
'matching\productMatcher.js','search\buildSearchQuery.js','search\searchProvider.js','compare\price.js','compare\collection.js','compare\productCard.js')
foreach($f in $files){if(-not(Test-Path -LiteralPath(Join-Path $source $f)-PathType Leaf)){throw "Missing input: $f"}}
foreach($f in @('manifest.json','platform.js')){if(-not(Test-Path -LiteralPath(Join-Path $platform $f)-PathType Leaf)){throw "Missing platform input: $f"}}
function Gate{Push-Location(Join-Path $root 'find-cheaper-backend');try{& npm.cmd test;if($LASTEXITCODE){throw 'Backend tests failed'}}finally{Pop-Location};Push-Location $source;try{& node --test tests/integration.test.js tests/browser-adapter.test.js tests/safari-port.test.js tests/auth-flow-0.3.6.test.js;if($LASTEXITCODE){throw 'Extension tests failed'};& node tests/core.test.js;if($LASTEXITCODE){throw 'Core tests failed'};& node tests/find-cheaper.test.js;if($LASTEXITCODE){throw 'Find tests failed'}}finally{Pop-Location}}
function CopyInput($to){New-Item -ItemType Directory -Force $to|Out-Null;foreach($f in $files){$d=Join-Path $to $f;New-Item -ItemType Directory -Force(Split-Path $d)|Out-Null;Copy-Item -LiteralPath(Join-Path $source $f)-Destination $d};Copy-Item -LiteralPath(Join-Path $platform 'manifest.json')-Destination(Join-Path $to 'manifest.json');Copy-Item -LiteralPath(Join-Path $platform 'platform.js')-Destination(Join-Path $to 'platform.js')}
function Overrides($to){
$p=Join-Path $to 'popup.html';$s=Get-Content -Raw -Encoding utf8 $p;$n='<script src="popup.js"></script>';if(([regex]::Matches($s,[regex]::Escape($n)).Count)-ne 1-or$s-match'<script src="platform\.js">'){throw 'Unexpected popup layout'};$s=$s.Replace($n,'<script src="platform.js"></script><script src="popup.js"></script>');Set-Content $p $s -Encoding utf8
$p=Join-Path $to 'compare.html';$s=Get-Content -Raw -Encoding utf8 $p;if(($s|Select-String '<script src="search/demoCatalog\.js"></script>' -AllMatches).Matches.Count-ne 1){throw 'Unexpected compare layout'};$s=$s-replace'\s*<script src="search/demoCatalog\.js"></script>','';Set-Content $p $s -Encoding utf8
$p=Join-Path $to 'search\searchProvider.js';$s=Get-Content -Raw -Encoding utf8 $p;$old='const BACKEND_SEARCH_URL = "http://127.0.0.1:8787/api/search";';if(([regex]::Matches($s,[regex]::Escape($old)).Count)-ne 1){throw 'Unexpected provider layout'};$s=$s.Replace($old,'const BACKEND_SEARCH_URL = ComprRuntimeConfig.apiBaseUrl + "/api/search";').Replace('local-demo-catalog','backend').Replace('offline-demo','unavailable').Replace('ComprDemoCatalog','undefined').Replace('COMPR development backend unavailable; using offline demo','COMPR backend unavailable');Set-Content $p $s -Encoding utf8
$mode=if($UseTestFixture){'test-fixture'}else{'production'};$vals=@($api,$SupabaseUrl.TrimEnd('/'),$SupabaseAnonKey,$AuthCallbackUrl,$mode,(([uri]::new($callbackUri,'.')).AbsoluteUri.TrimEnd('/')+'/#beta-access'))|ForEach-Object{$_|ConvertTo-Json -Compress};$runtime="// Generated public Safari configuration. Never add private server secrets here.`nconst ComprRuntimeConfig = Object.freeze({`n  apiBaseUrl: $($vals[0]),`n  supabaseUrl: $($vals[1]),`n  supabaseAnonKey: $($vals[2]),`n  authCallbackUrl: $($vals[3]),`n  mode: $($vals[4]),`n  betaMode: true,`n  betaAccessUrl: $($vals[5]),`n  storeReviewUrl: `"`",`n  platform: `"safari`",`n  guestMode: false`n});`n";Set-Content(Join-Path $to 'shared\runtimeConfig.js')$runtime -Encoding utf8
$p=Join-Path $to 'manifest.json';$m=Get-Content -Raw -Encoding utf8 $p|ConvertFrom-Json;$m.host_permissions=@("$api/*","$($SupabaseUrl.TrimEnd('/'))/*",'https://www.ecb.europa.eu/*');$m.web_accessible_resources[0].matches=@($callbackUri.GetLeftPart('Authority')+'/*');$m|ConvertTo-Json -Depth 20|Set-Content $p -Encoding utf8}
function Validate($to){$m=Get-Content -Raw -Encoding utf8 (Join-Path $to 'manifest.json')|ConvertFrom-Json;if($m.manifest_version-ne3-or$m.background.service_worker-ne'background.js'-or$null-ne$m.content_scripts-or$m.host_permissions-contains'<all_urls>'-or@($m.permissions|Where-Object{$_-notin@('storage','activeTab','scripting')}).Count){throw 'Unsafe manifest'};$inv=@(Get-ChildItem $to -Recurse -File|ForEach-Object{$_.FullName.Substring($to.Length+1).Replace('\','/')}|Sort-Object);$expected=@($files+@('manifest.json','platform.js','shared\runtimeConfig.js')|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique);if(@($inv|Where-Object{$_-notin$expected}).Count-or@($expected|Where-Object{$_-notin$inv}).Count){throw 'Inventory mismatch'};$bad=@(Get-ChildItem $to -Recurse -Force|Where-Object{$_.Name-match'(?i)^\.git|^\.env|node_modules|screenshots?|\.map$|\.log$|\.zip$|\.ps1$|readme|audit|checklist|test\.js$|fixture|preview|deriveddata|\.p12$|\.pem$|\.key$|\.mobileprovision$'});if($bad){throw 'Forbidden output file'};$unsafe=@(Get-ChildItem $to -Recurse -File|Select-String -Pattern'sk_live_','sk_test_','whsec_','service_role','127\.0\.0\.1','localhost','demoCatalog','offline-demo','comprshop\.github\.io','vercel\.app','[A-Za-z]:\\Users\\','C:/Users/','/Users/[^<\s]+' -AllMatches);if($unsafe){throw 'Unsafe output content'};Assert-ExtensionOutputSafety -Root $to;foreach($j in Get-ChildItem $to -Recurse -File -Filter *.js){& node --check $j.FullName;if($LASTEXITCODE){throw"Syntax failure: $($j.Name)"}};$html=Get-Content -Raw -Encoding utf8 (Join-Path $to 'popup.html');if(([regex]::Matches($html,'<script src="platform\.js"></script>').Count)-ne1-or$html.IndexOf('<script src="platform.js"></script>')-gt$html.IndexOf('<script src="popup.js"></script>')){throw 'Platform load order failure'};return $inv}
Gate
$workRoot=if($ValidationOnly){$tmp}else{$build}
$workPrefix=if($ValidationOnly){'safari-validation-'}else{'.safari-stage-'}
New-Item -ItemType Directory -Force -Path $workRoot|Out-Null
$work=Join-Path $workRoot ($workPrefix+[guid]::NewGuid().ToString('N'))
$keep=$false
try{CopyInput $work;Overrides $work;$inventory=@(Validate $work);if($ShowInventory){$inventory|ForEach-Object{Write-Host " - $_"}};if($ValidationOnly){Write-Host "Safari validation passed ($($inventory.Count) files); no artifact was retained."}else{$out=if($OutputPath){if([IO.Path]::IsPathRooted($OutputPath)){$OutputPath}else{Join-Path $root $OutputPath}}else{Join-Path $build 'safari-converter-input'};$out=[IO.Path]::GetFullPath($out);$prefix=$build.TrimEnd('\')+'\';if(-not$out.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Output must remain under build.'};if(Test-Path $out){$resolved=[IO.Path]::GetFullPath((Resolve-Path $out).Path);if(-not$resolved.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Unsafe existing output'};Remove-Item -LiteralPath $resolved -Recurse -Force};New-Item -ItemType Directory -Force -Path (Split-Path -Parent $out)|Out-Null;Move-Item $work $out;$keep=$true;Write-Host "Safari converter input staged ($($inventory.Count) files).";Write-Host 'Public Supabase client configuration source must be owner-confirmed before transfer.'}}finally{if(-not$keep-and(Test-Path $work)){Remove-Item -LiteralPath $work -Recurse -Force}}
